def make_grid_str(grid):
    """Create a string representation of the grid"""
    result = []
    for r in range(rows):
        row_str = ""
        for c in range(cols):
            v = grid[r][c]
            if v == 6:
                row_str += "•"  # wall/filled
            elif v == 0:
                row_str += "."  # empty/path
            elif v == 1:
                row_str += "*"  # special
        result.append(row_str)
    return "\n".join(result)

