def get_all_isolated_objects(grid, skip_val=6):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    objects = []

    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        cells = [(r, c)]
        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != skip_val:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
                    cells.append((nr, nc))
        return cells

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != skip_val and not visited[r][c]:
                obj = bfs(r, c)
                if len(obj) > 0:
                    values = set(input_grid[r][c] for r, c in obj)
                    objects.append((len(obj), sorted(values), obj))

    return objects

