def find_enclosed_regions(grid):
    """Find regions completely surrounded by background"""
    rows, cols = len(grid), len(grid[0])

    # First, find all reachable cells from edges
    edge_visited = [[False]*cols for _ in range(rows)]
    queue = deque()

    for r in range(rows):
        for c in [0, cols-1]:
            if 0 <= r < rows and 0 <= c < cols:
                if grid[r][c] != 6:  # Non-background on edge
                    queue.append((r, c))
                    edge_visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not edge_visited[nr][nc] and grid[nr][nc] != 6:
                    edge_visited[nr][nc] = True
                    queue.append((nr, nc))

    # Now find non-background cells NOT visited (completely enclosed)
    enclosed = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 6 and not edge_visited[r][c]:
                enclosed.append((r, c))

    return enclosed, edge_visited

